parameters.jsCode:
const clips = $input.all().filter((i) => i.json && i.json.id);
if (clips.length === 0) {
  return [{ json: { hasVideo: false } }];
}

const shuffled = clips
  .map((c) => c.json)
  .sort(() => Math.random() - 0.5);

const unique = [];
const seen = new Set();
for (const clip of shuffled) {
  if (seen.has(clip.id)) continue;
  seen.add(clip.id);
  unique.push(clip);
  if (unique.length >= 6) break;
}

const target = Math.max(3, Math.min(6, unique.length || 3));
const picks = [];
while (picks.length < target) {
  picks.push(unique[picks.length % unique.length]);
}

const videoUrls = picks.map(
  (p) => `https://drive.google.com/uc?export=download&confirm=t&id=${p.id}`
);

return [{
  json: {
    hasVideo: true,
    videoUrl: videoUrls[0],
    videoUrls,
    fileIds: picks.map((p) => p.id),
    fileNames: picks.map((p) => p.name),
    clipCount: unique.length,
    uniqueClipCount: unique.length,
    needsMoreClips: unique.length < 3,
  },
}];

parameters.input:
={{
(() => {
  let raw =
    $('AI Content').item.json.output?.[0]?.content?.[0]?.text
    ?? $('AI Content').item.json.message?.content
    ?? $('AI Content').item.json.text
    ?? $('AI Content').item.json;

  if (typeof raw === 'string') {
    try { raw = JSON.parse(raw); } catch (e) { /* keep as string */ }
  }

  const ai = (raw && typeof raw === 'object') ? raw : {};
  const scenes = Array.isArray(ai.video_scenes) ? ai.video_scenes : [];
  const sceneLines = scenes
    .map((s) => (s.text || '').toString().trim())
    .filter(Boolean)
    .slice(0, 3)
    .join('. ');

  const vo = (
    ai.voiceoverScript
    || ai.voiceover_script
    || ai.script
    || ai.hook
    || sceneLines
    || (ai.caption || '').toString().split('\n')[0]
    || 'Scholarship details are in the caption. Follow for more opportunities.'
  ).toString().trim();

  return vo.slice(0, 400);
})()
}}

