// Select Random Music — put after List Music Files
const rows = (typeof $input !== 'undefined' && $input.all)
  ? $input.all()
  : (typeof items !== 'undefined' ? items : []);

const files = rows
  .map((i) => i.json || i)
  .filter((f) => {
    if (!f || !f.id) return false;
    const name = (f.name || '').toLowerCase();
    const mime = (f.mimeType || f.mime_type || '').toLowerCase();
    return (
      name.endsWith('.mp3') ||
      name.endsWith('.wav') ||
      name.endsWith('.m4a') ||
      name.endsWith('.aac') ||
      mime.includes('audio')
    );
  });

if (!files.length) {
  throw new Error(
    'No music files found in Drive Music folder. Add .mp3/.wav/.m4a files and make sure List Music Files points to the Music folder.'
  );
}

const pick = files[Math.floor(Math.random() * files.length)];
const musicUrl = `https://drive.google.com/uc?export=download&confirm=t&id=${pick.id}`;

return [{
  json: {
    musicFileId: pick.id,
    musicName: pick.name,
    musicUrl,
  },
}];

const musicUrl = (
  $json.musicUrl ||
  $json.music_url ||
  ($('Select Random Music').item.json || {}).musicUrl ||
  ($('Select Random Music').item.json || {}).music_url ||
  ''
).toString().trim();

const clipNode = $('Select Random Clip').item.json;
const sheet = $('Get Pending Scholarship').item.json;

const videoUrls = Array.isArray(clipNode.videoUrls) && clipNode.videoUrls.length
  ? clipNode.videoUrls
  : (clipNode.videoUrl ? [clipNode.videoUrl] : []);

if (!musicUrl) {
  throw new Error('No musicUrl. Check Drive Music folder has .mp3 files.');
}
if (!videoUrls.length) throw new Error('No videoUrls');

let ai = $('AI Content').item.json.output?.[0]?.content?.[0]?.text || $('AI Content').item.json;
if (typeof ai === 'string') {
  try { ai = JSON.parse(ai); } catch (e) { ai = {}; }
}

const scenes = Array.isArray(ai.video_scenes) ? ai.video_scenes : [];
const sceneText = (n) => (scenes.find((s) => Number(s.scene) === n)?.text || '').toString().trim();

const clean = (v, max) => (v || '').toString().replace(/\s+/g, ' ').trim().slice(0, max);
const dangling = new Set(['a','an','the','in','on','at','to','for','of','and','or','with','from']);

const completeLine = (v, max = 42) => {
  let t = clean(v, max + 10);
  if (!t) return '';
  if (t.length > max) {
    t = t.slice(0, max + 1);
    if (t.includes(' ')) t = t.slice(0, t.lastIndexOf(' '));
  }
  let words = t.split(/\s+/).filter(Boolean);
  while (words.length && dangling.has(words[words.length - 1].toLowerCase().replace(/[.,!?]/g, ''))) {
    words.pop();
  }
  return words.join(' ');
};

const country = completeLine(sheet['Host Country'] || '', 28);
const university = completeLine(sheet['University'] || '', 40);
const degree = completeLine(sheet['Degree Type'] || '', 36);
const fieldRaw = clean(sheet['Field of Study'] || '', 60);
const fieldShort = completeLine((fieldRaw.split(/[,/|]/)[0] || fieldRaw), 30);
const deadline = completeLine(sheet['Deadline'] || '', 28);
const benefitRaw = completeLine(
  sheet['Scholarship Type'] || ai.hook || sceneText(5) || '',
  40
);

const fromScenes = scenes
  .map((s) => completeLine(s.text, 42))
  .filter(Boolean);

// Preferred structured slides (complete ideas)
const structured = [];
structured.push(
  completeLine(
    ai.hook || ai.headline || sceneText(1) || (country ? `Fully Funded Scholarships in ${country}` : 'Fully Funded Scholarships'),
    42
  )
);
if (university) structured.push(university);
else if (ai.university_line) structured.push(completeLine(ai.university_line, 40));

if (degree) structured.push(degree);
else if (ai.audience_line) structured.push(completeLine(ai.audience_line, 36));

if (fieldShort) structured.push(completeLine(ai.field_line || `Field: ${fieldShort}`, 40));
else if (ai.field_line) structured.push(completeLine(ai.field_line, 40));

if (benefitRaw && !/fully funded/i.test(benefitRaw)) structured.push(benefitRaw);
else if (sceneText(5)) structured.push(completeLine(sceneText(5), 40));

if (deadline) structured.push(completeLine(`Deadline: ${deadline}`, 40));

const cta = completeLine(ai.cta || sceneText(7) || sceneText(6) || 'Apply Now', 36) || 'Apply Now';
structured.push(cta);

// Unique non-empty slides, max 6
const texts = [];
const seen = new Set();
for (const line of [...structured, ...fromScenes]) {
  const key = (line || '').toLowerCase();
  if (!line || seen.has(key)) continue;
  if (dangling.has(key.split(/\s+/).pop())) continue;
  seen.add(key);
  texts.push(line);
  if (texts.length >= 6) break;
}
while (texts.length < 3) texts.push('Follow for more scholarships');

const uniqueUrls = [];
for (const u of videoUrls) {
  if (u && !uniqueUrls.includes(u)) uniqueUrls.push(u);
}
while (uniqueUrls.length < texts.length && videoUrls.length) {
  uniqueUrls.push(videoUrls[uniqueUrls.length % videoUrls.length]);
}

const hook = texts[0];
const script = texts[Math.min(1, texts.length - 1)];
const ctaOut = texts[texts.length - 1];
const bio = clean(ai.bio || ai.profile_bio || '', 150);

const payload = {
  video_url: uniqueUrls[0],
  video_urls: uniqueUrls.slice(0, texts.length),
  music_url: musicUrl,
  texts,
  hook,
  script,
  cta: ctaOut,
  duration_seconds: Math.min(18, Math.max(12, texts.length * 2.5)),
  music_volume: 0.38,
};

return [{
  json: {
    ...payload,
    video_urls_text: payload.video_urls.join('\n'),
    render_body: JSON.stringify(payload),
    profile_bio: bio,
    caption: (ai.caption || '').toString().trim(),
    hashtags: Array.isArray(ai.hashtags) ? ai.hashtags : [],
    field_of_study: fieldShort,
  },
}];
